conditionals.body:
荷载分配计算\:
q1=${IsLarge(GLS_tm,3.0):+1.1×}q×t1^3/(t1^3+t2^3)
  =${IsLarge(GLS_tm,3.0):+1.1×}${GLS_COMP}×${GLS_to}^3/(${GLS_to}^3+${GLS_ti}^3)
  =${GLS_qwo}
q2=q×t2^3/(t1^3+t2^3)
  =${GLS_COMP}×${GLS_ti}^3/(${GLS_to}^3+${GLS_ti}^3)
  =${GLS_qwi}
qk1=${IsLarge(GLS_tm,3.0):+1.1×}qk×t1^3/(t1^3+t2^3)
  =${IsLarge(GLS_tm,3.0):+1.1×}${GLS_COMPK}×${GLS_to}^3/(${GLS_to}^3+${GLS_ti}^3)
  =${GLS_qwko}
qk2=qk×t2^3/(t1^3+t2^3)
  =${GLS_COMPK}×${GLS_ti}^3/(${GLS_to}^3+${GLS_ti}^3)
  =${GLS_qwki}

荷载分配计算\:
q1=${IsLarge(GLS_tmg,3.0):+1.1×}q×t1^3/(t1^3+t2^3)
  =${IsLarge(GLS_tmg,3.0):+1.1×}${GLS_COMP}×${GLS_to}^3/(${GLS_to}^3+${GLS_ti}^3)
  =${GLS_qwo}
q2=q×t2^3/(t1^3+t2^3)
  =${GLS_COMP}×${GLS_t2}^3/(${GLS_t1}^3+${GLS_t2}^3)
  =${GLS_qwi}
qk1=${IsLarge(GLS_tmg,3.0):+1.1×}qk×t1^3/(t1^3+t2^3)
  =${IsLarge(GLS_tmg,3.0):+1.1×}${GLS_COMPK}×${GLS_to}^3/(${GLS_to}^3+${GLS_ti}^3)
  =${GLS_qwko}
qk2=qk×t2^3/(t1^3+t2^3)
  =${GLS_COMPK}×${ti}^3/(${GLS_to}^3+${GLS_ti}^3)
  =${GLS_qwki}

r1,r2,r3\:外层、中间层、内层玻璃荷载分配系数
r1 =t1^3/(t1^3+t2^3+t3^3)
   =${GLS_to}^3/(${GLS_to}^3+${GLS_tmg}^3+${GLS_ti}^3)
   =${GLS_RGLASS0}
r2 =t2^3/(t1^3+t2^3+t3^3)
   =${GLS_tmg}^3/(${GLS_to}^3+${GLS_tmg}^3+${GLS_ti}^3)
   =${GLS_RGLASS1}
r3 =t3^3/(t1^3+t2^3+t3^3)
   =${GLS_ti}^3/(${GLS_to}^3+${GLS_tmg}^3+${GLS_ti}^3)
   =${GLS_RGLASS2}

当前玻璃结构为${GLS_DESC}
r1,r2,r3\:外层、中间层、内层玻璃荷载分配系数
r1 =1.1×t1^3/(t1^3+t2^3+t3^3)
   =1.1×${GLS_to}^3/(${GLS_to}^3+${GLS_tmg}^3+${GLS_ti}^3)
   =${GLS_RGLASS0}
r2 =t2^3/(t1^3+t2^3+t3^3)
   =${GLS_tmg}^3/(${GLS_to}^3+${GLS_tmg}^3+${GLS_ti}^3)
   =${GLS_RGLASS1}
r3 =t3^3/(t1^3+t2^3+t3^3)
   =${GLS_ti}^3/(${GLS_to}^3+${GLS_tmg}^3+${GLS_ti}^3)
   =${GLS_RGLASS2}

r1,r2,r3\:外层、中间层、内层玻璃荷载分配系数
r1 =t1^3/(t1^3+t2^3+t3^3)
   =${GLS_to}^3/(${GLS_to}^3+${GLS_tmg}^3+${GLS_ti}^3)
   =${GLS_RGLASS0}
r2 =t2^3/(t1^3+t2^3+t3^3)
   =${GLS_RGLASS1}
r3 =t3^3/(t1^3+t2^3+t3^3)
   =${GLS_RGLASS2}

当前玻璃结构为${GLS_DESC}
r1,r2,r3\:外层、中间层、内层玻璃荷载分配系数
r1 =1.1×t1^3/(t1^3+t2^3+t3^3)
   =${GLS_RGLASS0}
r2 =t2^3/(t1^3+t2^3+t3^3)
   =${GLS_RGLASS1}
r3 =t3^3/(t1^3+t2^3+t3^3)
   =${GLS_RGLASS2}

${GetEQSSubFormat('r','','1')},${GetEQSSubFormat('r','','2')},${GetEQSSubFormat('r','','3')}\:外层、中间层、内层玻璃荷载分配系数
${GetEQSSubFormat('r','','1')} =${GetEQFormat(0)}\\f(${GetSSubFormat('t','','1')}^3,${GetSSubFormat('t','','1')}^3+${GetSSubFormat('t','','2')}^3+${GetSSubFormat('t','','3')}^3)${GetEQFormat(1)}
   =${GetEQFormat(0)}\\f(${GLS_to}^3,${GLS_to}^3+${GLS_tmg}^3+${GLS_ti}^3)${GetEQFormat(1)}
   =${GLS_RGLASS0}
${GetEQSSubFormat('r','','2')} =${GetEQFormat(0)}\\f(${GetSSubFormat('t','','2')}^3,${GetSSubFormat('t','','1')}^3+${GetSSubFormat('t','','2')}^3+${GetSSubFormat('t','','3')}^3)${GetEQFormat(1)}
   =${GetEQFormat(0)}\\f(${GLS_tmg}^3,${GLS_to}^3+${GLS_tmg}^3+${GLS_ti}^3)${GetEQFormat(1)}
   =${GLS_RGLASS1}
${GetEQSSubFormat('r','','3')} =${GetEQFormat(0)}\\f(t3^3,${GetSSubFormat('t','','1')}^3+${GetSSubFormat('t','','2')}^3+${GetSSubFormat('t','','3')}^3)${GetEQFormat(1)}
   =${GetEQFormat(0)}\\f(${GLS_ti}^3,${GLS_to}^3+${GLS_tmg}^3+${GLS_ti}^3)${GetEQFormat(1)}
   =${GLS_RGLASS2}

当前玻璃结构为${GLS_DESC},考虑外层夹胶先组合然后与内层再组合的原则
${GetEQSSubFormat('t','','ew')}\:外层夹胶组合等效厚度
${GetEQSSubFormat('t','','ew')}=${GetEQFormat(0)}\\r(3,${GetSSubFormat('t','','1')}^3+${GetSSubFormat('t','','2')}^3)${GetEQFormat(1)}
${GetEQSSubFormat('r','','ew')}\:外层夹胶组合分配系数
${GetEQSSubFormat('r','','ew')}=1.1×${GetEQFormat(0)}\\f(${GetSSubFormat('t','','ew')}^3,${GetSSubFormat('t','','ew')}^3+${GetSSubFormat('t','','2')}^3)${GetEQFormat(1)}
   =1.1×${GetEQFormat(0)}\\f(${GetSSubFormat('t','','1')}^3+t2^3,${GetSSubFormat('t','','1')}^3+${GetSSubFormat('t','','2')}^3+${GetSSubFormat('t','','3')}^3)${GetEQFormat(1)}
${GetEQSSubFormat('r','','1')},${GetEQSSubFormat('r','','2')},${GetEQSSubFormat('r','','3')}\:外层、中间层、内层玻璃荷载分配系数
${GetEQSSubFormat('r','','1')} =${GetEQSSubFormat('r','','ew')}×${GetEQFormat(0)}\\f(${GetSSubFormat('t','','1')}^3,${GetSSubFormat('t','','1')}^3+${GetSSubFormat('t','','2')}^3)${GetEQFormat(1)}
   =1.1×${GetEQFormat(0)}\\f(${GetSSubFormat('t','','1')}^3+${GetSSubFormat('t','','2')}^3,${GetSSubFormat('t','','1')}^3+${GetSSubFormat('t','','2')}^3+${GetSSubFormat('t','','3')}^3)${GetEQFormat(1)}×${GetEQFormat(0)}\\f(${GetSSubFormat('t','','1')}^3,${GetSSubFormat('t','','1')}^3+${GetSSubFormat('t','','2')}^3)${GetEQFormat(1)}
   =1.1×${GetEQFormat(0)}\\f(${GLS_to}^3,${GLS_to}^3+${GLS_tmg}^3+${GLS_ti}^3)${GetEQFormat(1)}
   =${GLS_RGLASS0}
${GetEQSSubFormat('r','','2')} =${GetEQSSubFormat('r','','ew')} × ${GetEQFormat(0)}\\f(${GetSSubFormat('t','','2')}^3,${GetSSubFormat('t','','1')}^3+${GetSSubFormat('t','','2')}^3)${GetEQFormat(1)}
   =1.1 × ${GetEQFormat(0)}\\f(t2^3,${GetSSubFormat('t','','1')}^3+${GetSSubFormat('t','','2')}^3+${GetSSubFormat('t','','3')}^3)${GetEQFormat(1)}
   =1.1 × ${GetEQFormat(0)}\\f(${GLS_tmg}^3,${GLS_to}^3+${GLS_tmg}^3+${GLS_ti}^3)${GetEQFormat(1)}
   =${GLS_RGLASS1}
${GetEQSSubFormat('r','','3')} =${GetEQFormat(0)}\\f(${GetSSubFormat('t','','3')}^3,${GetSSubFormat('t','','ew')}^3+${GetSSubFormat('t','','3')}^3)${GetEQFormat(1)}
   =${GetEQFormat(0)}\\f(${GetSSubFormat('t','','3')}^3,${GetSSubFormat('t','','1')}^3+${GetSSubFormat('t','','2')}^3+${GetSSubFormat('t','','3')}^3)${GetEQFormat(1)}
   =${GetEQFormat(0)}\\f(${GLS_ti}^3,${GLS_to}^3+${GLS_tmg}^3+${GLS_ti}^3)${GetEQFormat(1)}
   =${GLS_RGLASS2}

当前玻璃结构为${GLS_DESC},考虑内层夹胶先组合然后与外层中空再组合的原则
${GetEQSSubFormat('t','','en')}\:内层夹胶组合等效厚度
${GetEQSSubFormat('t','','en')}=${GetEQFormat(0)}\\r(3,${GetSSubFormat('t','','2')}^3+${GetSSubFormat('t','','3')}^3)${GetEQFormat(1)}
${GetEQSSubFormat('r','','en')}\:内层夹胶组合分配系数
${GetEQSSubFormat('r','','en')}=${GetEQFormat(0)}\\f(${GetSSubFormat('t','','en')}^3,${GetSSubFormat('t','','en')}^3+${GetSSubFormat('t','','1')}^3)${GetEQFormat(1)}
   =${GetEQFormat(0)}\\f(${GetSSubFormat('t','','2')}^3+${GetSSubFormat('t','','3')}^3,${GetSSubFormat('t','','2')}^3+${GetSSubFormat('t','','3')}^3+${GetSSubFormat('t','','1')}^3)${GetEQFormat(1)}
${GetEQSSubFormat('r','','1')},${GetEQSSubFormat('r','','2')},${GetEQSSubFormat('r','','3')}\:外层、中间层、内层玻璃荷载分配系数
${GetEQSSubFormat('r','','1')} =1.1×${GetEQFormat(0)}\\f(${GetSSubFormat('t','','1')}^3,${GetSSubFormat('t','','1')}^3+${GetSSubFormat('t','','en')}^3)${GetEQFormat(1)}
   =1.1×${GetEQFormat(0)}\\f(${GetSSubFormat('t','','1')}^3,${GetSSubFormat('t','','1')}^3+${GetSSubFormat('t','','2')}^3+${GetSSubFormat('t','','3')}^3)${GetEQFormat(1)}
   =1.1×${GetEQFormat(0)}\\f(${GLS_to}^3,${GLS_to}^3+${GLS_tmg}^3+${GLS_ti}^3)${GetEQFormat(1)}
   =${GLS_RGLASS0}
${GetEQSSubFormat('r','','2')} =${GetEQSSubFormat('r','','en')}×${GetEQFormat(0)}\\f(${GetSSubFormat('t','','2')}^3,${GetSSubFormat('t','','2')}^3+${GetSSubFormat('t','','3')}^3)${GetEQFormat(1)}
   =${GetEQFormat(0)}\\f(${GetSSubFormat('t','','2')}^3+${GetSSubFormat('t','','3')}^3,${GetSSubFormat('t','','2')}^3+${GetSSubFormat('t','','3')}^3+${GetSSubFormat('t','','1')}^3)${GetEQFormat(1)}×${GetEQFormat(0)}\\f(${GetSSubFormat('t','','2')}^3,${GetSSubFormat('t','','2')}^3+${GetSSubFormat('t','','3')}^3)${GetEQFormat(1)}
   =${GetEQFormat(0)}\\f(${GLS_tmg}^3,${GLS_to}^3+${GLS_tmg}^3+${GLS_ti}^3)${GetEQFormat(1)}
   =${GLS_RGLASS1}
${GetEQSSubFormat('r','','3')} =${GetEQSSubFormat('r','','en')}×${GetEQFormat(0)}\\f(${GetSSubFormat('t','','3')}^3,${GetSSubFormat('t','','2')}^3+${GetSSubFormat('t','','3')}^3)${GetEQFormat(1)}
   =${GetEQFormat(0)}\\f(t3^3,${GetSSubFormat('t','','1')}^3+${GetSSubFormat('t','','2')}^3+t3^3)${GetEQFormat(1)}
   =${GetEQFormat(0)}\\f(${GLS_ti}^3,${GLS_to}^3+${GLS_tmg}^3+${GLS_ti}^3)${GetEQFormat(1)}
   =${GLS_RGLASS2}

当前玻璃结构为${GLS_DESC}
${GetEQSSubFormat('r','','1')},${GetEQSSubFormat('r','','2')},${GetEQSSubFormat('r','','3')}\:外层、中间层、内层玻璃荷载分配系数
${GetEQSSubFormat('r','','1')} =1.1×${GetEQFormat(0)}\\f(${GetSSubFormat('t','','1')}^3,${GetSSubFormat('t','','1')}^3+${GetSSubFormat('t','','2')}^3+${GetSSubFormat('t','','3')}^3)${GetEQFormat(1)}
   =1.1×${GetEQFormat(0)}\\f(${GLS_to}^3,${GLS_to}^3+${GLS_tmg}^3+${GLS_ti}^3)${GetEQFormat(1)}
   =${GLS_RGLASS0}
${GetEQSSubFormat('r','','2')} =${GetEQFormat(0)}\\f(${GetSSubFormat('t','','2')}^3,${GetSSubFormat('t','','1')}^3+${GetSSubFormat('t','','2')}^3+${GetSSubFormat('t','','3')}^3)${GetEQFormat(1)}
   =${GetEQFormat(0)}\\f(${GLS_tmg}^3,${GLS_to}^3+${GLS_tmg}^3+${GLS_ti}^3)${GetEQFormat(1)}
   =${GLS_RGLASS1}
${GetEQSSubFormat('r','','3')} =${GetEQFormat(0)}\\f(${GetSSubFormat('t','','3')}^3,${GetSSubFormat('t','','1')}^3+${GetSSubFormat('t','','2')}^3+${GetSSubFormat('t','','3')}^3)${GetEQFormat(1)}
   =${GetEQFormat(0)}\\f(${GLS_ti}^3,${GLS_to}^3+${GLS_tmg}^3+${GLS_ti}^3)${GetEQFormat(1)}
   =${GLS_RGLASS2}

${GetEQSSubFormat('r','','1')},${GetEQSSubFormat('r','','2')},${GetEQSSubFormat('r','','3')}\:外层、中间层、内层玻璃荷载分配系数
${GetEQSSubFormat('r','','1')} =${GetEQFormat(0)}\\f(${GetSSubFormat('t','','1')}^3,${GetSSubFormat('t','','1')}^3+${GetSSubFormat('t','','2')}^3+${GetSSubFormat('t','','3')}^3)${GetEQFormat(1)}
   =${GetEQFormat(0)}\\f(${GLS_to}^3,${GLS_to}^3+${GLS_tmg}^3+${GLS_ti}^3)${GetEQFormat(1)}
   =${GLS_RGLASS0}
${GetEQSSubFormat('r','','2')} =${GetEQFormat(0)}\\f(${GetSSubFormat('t','','2')}^3,${GetSSubFormat('t','','1')}^3+${GetSSubFormat('t','','2')}^3+${GetSSubFormat('t','','3')}^3)${GetEQFormat(1)}
   =${GetEQFormat(0)}\\f(${GLS_tmg}^3,${GLS_to}^3+${GLS_tmg}^3+${GLS_ti}^3)${GetEQFormat(1)}
   =${GLS_RGLASS1}
${GetEQSSubFormat('r','','3')} =${GetEQFormat(0)}\\f(t3^3,${GetSSubFormat('t','','1')}^3+${GetSSubFormat('t','','2')}^3+${GetSSubFormat('t','','3')}^3)${GetEQFormat(1)}
   =${GetEQFormat(0)}\\f(${GLS_ti}^3,${GLS_to}^3+${GLS_tmg}^3+${GLS_ti}^3)${GetEQFormat(1)}
   =${GLS_RGLASS2}

当前玻璃结构为${GLS_DESC},考虑外层夹胶先组合然后与内层再组合的原则
${GetEQSSubFormat('t','','ew')}\:外层夹胶组合等效厚度
${GetEQSSubFormat('t','','ew')}=${GetEQFormat(0)}\\r(3,${GetSSubFormat('t','','1')}^3+${GetSSubFormat('t','','2')}^3)${GetEQFormat(1)}
${GetEQSSubFormat('r','','ew')}\:外层夹胶组合分配系数
${GetEQSSubFormat('r','','ew')}=1.1×${GetEQFormat(0)}\\f(${GetSSubFormat('t','','ew')}^3,${GetSSubFormat('t','','ew')}^3+${GetSSubFormat('t','','2')}^3)${GetEQFormat(1)}
   =1.1×${GetEQFormat(0)}\\f(${GetSSubFormat('t','','1')}^3+t2^3,${GetSSubFormat('t','','1')}^3+${GetSSubFormat('t','','2')}^3+${GetSSubFormat('t','','3')}^3)${GetEQFormat(1)}
${GetEQSSubFormat('r','','1')},${GetEQSSubFormat('r','','2')},${GetEQSSubFormat('r','','3')}\:外层、中间层、内层玻璃荷载分配系数
${GetEQSSubFormat('r','','1')} =${GetEQSSubFormat('r','','ew')}×${GetEQFormat(0)}\\f(${GetSSubFormat('t','','1')}^3,${GetSSubFormat('t','','1')}^3+${GetSSubFormat('t','','2')}^3)${GetEQFormat(1)}
   =1.1×${GetEQFormat(0)}\\f(${GetSSubFormat('t','','1')}^3+${GetSSubFormat('t','','2')}^3,${GetSSubFormat('t','','1')}^3+${GetSSubFormat('t','','2')}^3+${GetSSubFormat('t','','3')}^3)${GetEQFormat(1)}×${GetEQFormat(0)}\\f(${GetSSubFormat('t','','1')}^3,${GetSSubFormat('t','','1')}^3+${GetSSubFormat('t','','2')}^3)${GetEQFormat(1)}
   =1.1×${GetEQFormat(0)}\\f(${GLS_to}^3,${GLS_to}^3+${GLS_tmg}^3+${GLS_ti}^3)${GetEQFormat(1)}
   =${GLS_RGLASS0}
${GetEQSSubFormat('r','','2')} =${GetEQSSubFormat('r','','ew')} × ${GetEQFormat(0)}\\f(${GetSSubFormat('t','','2')}^3,${GetSSubFormat('t','','1')}^3+${GetSSubFormat('t','','2')}^3)${GetEQFormat(1)}
   =1.1 × ${GetEQFormat(0)}\\f(t2^3,${GetSSubFormat('t','','1')}^3+${GetSSubFormat('t','','2')}^3+${GetSSubFormat('t','','3')}^3)${GetEQFormat(1)}
   =1.1 × ${GetEQFormat(0)}\\f(${GLS_tmg}^3,${GLS_to}^3+${GLS_tmg}^3+${GLS_ti}^3)${GetEQFormat(1)}
   =${GLS_RGLASS1}
${GetEQSSubFormat('r','','3')} =${GetEQFormat(0)}\\f(${GetSSubFormat('t','','3')}^3,${GetSSubFormat('t','','ew')}^3+${GetSSubFormat('t','','3')}^3)${GetEQFormat(1)}
   =${GetEQFormat(0)}\\f(${GetSSubFormat('t','','3')}^3,${GetSSubFormat('t','','1')}^3+${GetSSubFormat('t','','2')}^3+${GetSSubFormat('t','','3')}^3)${GetEQFormat(1)}
   =${GetEQFormat(0)}\\f(${GLS_ti}^3,${GLS_to}^3+${GLS_tmg}^3+${GLS_ti}^3)${GetEQFormat(1)}
   =${GLS_RGLASS2}

当前玻璃结构为${GLS_DESC},考虑内层夹胶先组合然后与外层中空再组合的原则
${GetEQSSubFormat('t','','en')}\:内层夹胶组合等效厚度
${GetEQSSubFormat('t','','en')}=${GetEQFormat(0)}\\r(3,${GetSSubFormat('t','','2')}^3+${GetSSubFormat('t','','3')}^3)${GetEQFormat(1)}
${GetEQSSubFormat('r','','en')}\:内层夹胶组合分配系数
${GetEQSSubFormat('r','','en')}=${GetEQFormat(0)}\\f(${GetSSubFormat('t','','en')}^3,${GetSSubFormat('t','','en')}^3+${GetSSubFormat('t','','1')}^3)${GetEQFormat(1)}
   =${GetEQFormat(0)}\\f(${GetSSubFormat('t','','2')}^3+${GetSSubFormat('t','','3')}^3,${GetSSubFormat('t','','2')}^3+${GetSSubFormat('t','','3')}^3+${GetSSubFormat('t','','1')}^3)${GetEQFormat(1)}
${GetEQSSubFormat('r','','1')},${GetEQSSubFormat('r','','2')},${GetEQSSubFormat('r','','3')}\:外层、中间层、内层玻璃荷载分配系数
${GetEQSSubFormat('r','','1')} =1.1×${GetEQFormat(0)}\\f(${GetSSubFormat('t','','1')}^3,${GetSSubFormat('t','','1')}^3+${GetSSubFormat('t','','en')}^3)${GetEQFormat(1)}
   =1.1×${GetEQFormat(0)}\\f(${GetSSubFormat('t','','1')}^3,${GetSSubFormat('t','','1')}^3+${GetSSubFormat('t','','2')}^3+${GetSSubFormat('t','','3')}^3)${GetEQFormat(1)}
   =1.1×${GetEQFormat(0)}\\f(${GLS_to}^3,${GLS_to}^3+${GLS_tmg}^3+${GLS_ti}^3)${GetEQFormat(1)}
   =${GLS_RGLASS0}
${GetEQSSubFormat('r','','2')} =${GetEQSSubFormat('r','','en')}×${GetEQFormat(0)}\\f(${GetSSubFormat('t','','2')}^3,${GetSSubFormat('t','','2')}^3+${GetSSubFormat('t','','3')}^3)${GetEQFormat(1)}
   =${GetEQFormat(0)}\\f(${GetSSubFormat('t','','2')}^3+${GetSSubFormat('t','','3')}^3,${GetSSubFormat('t','','2')}^3+${GetSSubFormat('t','','3')}^3+${GetSSubFormat('t','','1')}^3)${GetEQFormat(1)}×${GetEQFormat(0)}\\f(${GetSSubFormat('t','','2')}^3,${GetSSubFormat('t','','2')}^3+${GetSSubFormat('t','','3')}^3)${GetEQFormat(1)}
   =${GetEQFormat(0)}\\f(${GLS_tmg}^3,${GLS_to}^3+${GLS_tmg}^3+${GLS_ti}^3)${GetEQFormat(1)}
   =${GLS_RGLASS1}
${GetEQSSubFormat('r','','3')} =${GetEQSSubFormat('r','','en')}×${GetEQFormat(0)}\\f(${GetSSubFormat('t','','3')}^3,${GetSSubFormat('t','','2')}^3+${GetSSubFormat('t','','3')}^3)${GetEQFormat(1)}
   =${GetEQFormat(0)}\\f(t3^3,${GetSSubFormat('t','','1')}^3+${GetSSubFormat('t','','2')}^3+t3^3)${GetEQFormat(1)}
   =${GetEQFormat(0)}\\f(${GLS_ti}^3,${GLS_to}^3+${GLS_tmg}^3+${GLS_ti}^3)${GetEQFormat(1)}
   =${GLS_RGLASS2}

当前玻璃结构为${GLS_DESC}
${GetEQSSubFormat('r','','1')},${GetEQSSubFormat('r','','2')},${GetEQSSubFormat('r','','3')}\:外层、中间层、内层玻璃荷载分配系数
${GetEQSSubFormat('r','','1')} =1.1×${GetEQFormat(0)}\\f(${GetSSubFormat('t','','1')}^3,${GetSSubFormat('t','','1')}^3+${GetSSubFormat('t','','2')}^3+${GetSSubFormat('t','','3')}^3)${GetEQFormat(1)}
